mapper.select:
SELECT id, source_type, source_id, content_text, embedding, model_version, created_at, updated_at,
       1 - (embedding <=> #{queryVector, typeHandler=com.text2report.domain.vector.typehandler.PgVectorTypeHandler}::vector) AS similarity
FROM meta_embedding
WHERE source_type = #{sourceType}
ORDER BY embedding <=> #{queryVector, typeHandler=com.text2report.domain.vector.typehandler.PgVectorTypeHandler}::vector
LIMIT #{topK}

mapper.delete:
DELETE FROM meta_embedding
WHERE source_type = #{sourceType}
  AND source_id = #{sourceId}
